/* 超级管理员第二版补充页面：内容审核、须知文件与 P0 赛段管理。 */
(function(){
  Object.assign(labels,{review:'风采审核',noticeFiles:'须知文件管理',noticeFileForm:'新增须知文件'});
  const btn=(text,primary=true,action="showToast('操作已完成（Mock 演示）')")=>`<button class="${primary?'btn-primary':'btn-secondary'}" onclick="${action}">${text}</button>`;
  function competitionManagement(){return `<div class="page-heading"><div><h1>赛事管理</h1><p>管理赛事基本信息、参赛范围与完整状态流</p></div><div class="toolbar">${btn('新建赛事',true,"renderSuper('wizard')")}</div></div><section class="panel"><div class="panel-title"><span>2026 年岗位技能竞赛 · 赛事状态流</span><a>状态说明</a></div><div class="flow-line"><div class="flow-step done"><span>草稿</span><small>配置完成</small></div><div class="flow-step done"><span>已发布</span><small>已通知单位</small></div><div class="flow-step active"><span>进行中</span><small>初赛阶段</small></div><div class="flow-step"><span>已结束</span><small>待归档</small></div><div class="flow-step"><span>已归档</span><small>历史查询</small></div></div></section><div class="data-table-wrap" style="margin-top:14px"><div class="table-filter"><input placeholder="搜索赛事名称"/><select><option>全部状态</option><option>草稿</option><option>已发布</option><option>进行中</option><option>已结束</option><option>已归档</option></select>${btn('查询')}</div><table class="data-table"><thead><tr><th>赛事名称</th><th>赛事时间</th><th>参赛单位</th><th>参赛人数</th><th>状态</th><th>操作</th></tr></thead><tbody><tr><td>2026 年岗位技能竞赛</td><td>2026-06-01 至 08-31</td><td>32 家</td><td>8,426 人</td><td><span class="status green">进行中</span></td><td><a class="text-link">编辑</a><a class="text-link">查看数据</a></td></tr><tr><td>2025 年岗位技能竞赛</td><td>2025-06-01 至 08-30</td><td>28 家</td><td>7,960 人</td><td><span class="status gray">已归档</span></td><td><a class="text-link">查看归档</a></td></tr></tbody></table></div>`}
  function stagesManagement(){const stages=[['报名阶段','已结束','资格确认 8,426 人','发布赛段'],['初赛阶段','进行中','学习、答题与闯关积分累计','结束赛段'],['复赛阶段','待开始','专项挑战与晋级筛选','开启赛段'],['决赛阶段','待开始','总榜比拼与结果发布','开启赛段']];return `<div class="page-heading"><div><h1>赛段管理</h1><p>以赛段卡片管理报名、初赛、复赛和决赛，P0 不提供拖拽编排</p></div><div class="toolbar">${btn('新建赛段')}</div></div><section class="panel"><div class="panel-title"><span>2026 年岗位技能竞赛 · 赛段流程</span><a>线性流程</a></div><div class="stage-flow">${stages.map((x,i)=>`<article class="stage-flow-card ${i===1?'active':''}"><div class="stage-number"><span>赛段 0${i+1}</span><span class="status ${i===1?'green':'gray'}">${x[1]}</span></div><h3>${x[0]}</h3><p>时间：${['06-01 至 06-07','06-08 至 06-30','07-01 至 07-31','08-10 至 08-20'][i]}<br/>${x[2]}</p><div class="stage-foot"><a class="text-link" onclick="showToast('${x[3]}（Mock）')">${x[3]}</a><a class="text-link" onclick="showToast('打开规则配置')">配置规则</a><a class="text-link">查看数据</a></div></article>${i<3?'<div class="stage-flow-arrow"><span>➜</span></div>':''}`).join('')}</div></section><div class="p1-box">高级赛制编排（P1）：支持拖拽节点、连线、分支、合并和条件跳转。</div>`}
  function ruleConfig(type,title,desc){const fields={checkin:[['每日是否只能签到一次','是'],['每次签到积分','5 分'],['连续签到奖励','连续 7 天额外奖励 20 分'],['断签是否重置','是，连续天数重新计算'],['签到时间范围','每日 00:00 至 23:59'],['每日积分上限','5 分']],learning:[['绑定课程','初赛必修课程包（8 门）'],['是否必须完整观看','否'],['有效观看比例','≥ 80%'],['是否需要学后答题','是'],['答题通过分数','≥ 80 分'],['每日学习积分上限','60 分'],['重复学习是否计分','否']],gate:[['关卡数量','5 个分类，共 25 关'],['每关题目数量','3 题'],['题目来源','竞赛题库 · 安全生产专题'],['答题时间限制','每关 5 分钟'],['通关正确率','≥ 80%'],['每日挑战次数','每关每日 3 次'],['重复挑战规则','保留最高分'],['中途退出是否扣次数','是']]}[type];return `<div class="page-heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="toolbar">${btn('保存并发布')}</div></div><div class="config-grid"><section class="form-panel"><h3 style="margin-top:0">规则字段</h3><div class="form-row"><label>适用赛事</label><select><option>2026 年岗位技能竞赛</option></select></div><div class="form-row"><label>适用赛段</label><select><option>初赛阶段</option></select></div>${fields.map(x=>`<div class="form-row"><label>${x[0]}</label><input value="${x[1]}"/></div>`).join('')}</section><section class="form-panel"><div class="panel-title"><span>生效说明</span><a>预览用户端</a></div>${fields.map((x,i)=>`<div class="rule-card"><div class="rule-left"><div class="rule-icon">${['✓','✦','◉','☀','↗','◇','●','▤'][i]}</div><div><b>${x[0]}</b><p>${x[1]}</p></div></div><div class="toggle"></div></div>`).join('')}</section></div>`}
  function reviewPage(){const rows=[['我的安全生产答题复盘法','李雯','动力保障部','2026-06-23 09:20','经验分享','待审核','orange'],['班前十分钟学习法','赵勇','铸造车间','2026-06-22 16:15','图文感想','已通过','green'],['设备点检学习笔记','陈志远','电解二车间','2026-06-21 11:08','经验分享','已驳回','gray']];return `<div class="page-heading"><div><h1>风采审核</h1><p>审核用户发布的参赛心得、图文感想和经验分享</p></div><div class="toolbar">${btn('导出审核记录',false)}</div></div><div class="data-table-wrap"><div class="table-filter"><input placeholder="标题、发布人"/><select><option>全部</option><option>待审核</option><option>已通过</option><option>已驳回</option></select>${btn('筛选')}</div><table class="data-table"><thead><tr><th>标题</th><th>发布人</th><th>所属单位</th><th>提交时间</th><th>内容类型</th><th>审核状态</th><th>操作</th></tr></thead><tbody>${rows.map((x,i)=>`<tr>${x.slice(0,5).map(y=>`<td>${y}</td>`).join('')}<td><span class="status ${x[6]}">${x[5]}</span></td><td><a class="text-link" onclick="renderSuper('reviewDetail')">查看详情</a><a class="text-link" onclick="showToast('已审核通过')">通过</a><a class="text-link" onclick="showToast('已驳回，已记录审核意见')">驳回</a><a class="text-link" onclick="showToast('已删除 Mock 内容')">删除</a></td></tr>`).join('')}</tbody></table></div>`}
  function reviewDetail(){return `<div class="page-heading"><div><h1>风采审核详情</h1><p>审核用户提交的经验分享内容</p></div><div class="toolbar">${btn('返回列表',false,"renderSuper('review')")}</div></div><div class="config-grid"><section class="form-panel"><h2 style="margin-top:0">我的安全生产答题复盘法</h2><p style="color:#8794a7">发布人：李雯 · 动力保障部 · 2026-06-23 09:20</p><div style="height:150px;border-radius:10px;background:linear-gradient(135deg,#8c73d7,#b4a0eb);color:white;display:grid;place-items:center">图片占位 · 安全学习心得</div><p style="line-height:1.9;color:#5f6d80">先按类别整理错题，再用 15 分钟做一次限时挑战。通过课程重点与现场案例对照，能够更快掌握安全生产的关键要求。</p></section><section class="form-panel"><h3 style="margin-top:0">审核处理</h3><label style="display:block;margin-bottom:7px;color:#65738a">审核意见</label><textarea style="width:100%;height:120px;padding:10px;border:1px solid #dce4ef;border-radius:7px" placeholder="填写审核意见（Mock）"></textarea><div style="margin-top:16px;text-align:right">${btn('驳回',false,"showToast('已驳回该内容')")} ${btn('审核通过',true,"showToast('已审核通过并在发现页展示')")}</div></section></div>`}
  function noticeFiles(){const rows=[['2026 年岗位技能竞赛赛务指南','赛务指南','全赛事','全部赛段','2026-06-18','是','7,820','已发布'],['铝电解工竞赛技术文件','技术文件','全赛事','初赛阶段','2026-06-19','是','7,205','已发布'],['初赛考试大纲','考试大纲','全赛事','初赛阶段','2026-06-20','是','6,914','已发布'],['评分标准说明','评分标准','全赛事','复赛阶段','2026-06-21','否','1,120','草稿']];return `<div class="page-heading"><div><h1>须知文件管理</h1><p>维护移动端须知页展示的赛务指南、技术文件、考试大纲等资料</p></div><div class="toolbar">${btn('新增文件',true,"renderSuper('noticeFileForm')")}</div></div><div class="data-table-wrap"><div class="table-filter"><input placeholder="文件名称"/><select><option>全部分类</option><option>赛务指南</option><option>技术文件</option><option>考试大纲</option><option>竞赛规则</option><option>评分标准</option></select><select><option>全部发布状态</option><option>已发布</option><option>草稿</option></select><select><option>是否必读</option><option>是</option><option>否</option></select>${btn('查询')}</div><table class="data-table"><thead><tr><th>文件名称</th><th>分类</th><th>适用赛事</th><th>适用赛段</th><th>发布时间</th><th>必读</th><th>已读人数</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(x=>`<tr>${x.map((y,i)=>`<td>${i===5?`<span class="status ${y==='是'?'orange':'gray'}">${y}</span>`:i===7?`<span class="status ${y==='已发布'?'green':'gray'}">${y}</span>`:y}</td>`).join('')}<td><a class="text-link">编辑</a><a class="text-link" onclick="showToast('文件已发布')">发布</a><a class="text-link">下架</a><a class="text-link">删除</a></td></tr>`).join('')}</tbody></table></div>`}
  function noticeFileForm(){return `<div class="page-heading"><div><h1>新增须知文件</h1><p>Mock 表单，仅用于原型演示</p></div><div class="toolbar">${btn('返回列表',false,"renderSuper('noticeFiles')")}${btn('保存草稿')}</div></div><section class="form-panel"><div class="form-row"><label>文件名称</label><input placeholder="请输入文件名称"/></div><div class="form-row"><label>文件分类</label><select><option>赛务指南</option><option>技术文件</option><option>考试大纲</option><option>竞赛规则</option><option>评分标准</option><option>常见问题</option></select></div><div class="form-row"><label>适用赛事</label><select><option>2026 年岗位技能竞赛</option></select></div><div class="form-row"><label>适用赛段</label><select><option>初赛阶段</option><option>全部赛段</option></select></div><div class="form-row"><label>是否必读</label><select><option>是</option><option>否</option></select></div><div class="form-row"><label>文件上传</label><input value="上传文件占位（不执行真实上传）"/></div><div class="form-row"><label>正文内容</label><textarea style="height:140px;padding:10px;border:1px solid #dce4ef;border-radius:7px">请输入 mock 文件正文内容</textarea></div><div class="form-row"><label>发布状态</label><select><option>草稿</option><option>已发布</option></select></div><div style="text-align:right">${btn('保存并发布')}</div></section>`}
  window.renderSuper=function(page){const content=document.getElementById('superContent');if(!content)return;const map={dashboard:()=>dashboard(),wizard:()=>competitionWizard(),competitions:competitionManagement,stages:stagesManagement,units:()=>tablePage('units'),users:()=>tablePage('users'),checkin:()=>ruleConfig('checkin','签到规则配置','配置每日签到、连续签到和积分上限'),learning:()=>ruleConfig('learning','学习规则配置','配置课程学习、学后答题和学习积分'),gate:()=>ruleConfig('gate','闯关规则配置','配置关卡、题目、挑战次数和通关规则'),points:()=>tablePage('points'),ranking,promotion:()=>promotion(false),review:reviewPage,reviewDetail,noticeFiles,noticeFileForm};content.innerHTML=(map[page]||map.dashboard)();if(typeof normalizeStageTerms==='function')normalizeStageTerms(content);document.getElementById('crumb').textContent=labels[page]||labels.dashboard;bindControls()};
})();
